    // Gap #29 — proxy authentication propagation. The Squid fixture's
    // second port answers 407 unless the request carries Basic proxy
    // credentials, so a success through it proves the credentials embedded in
    // the proxy URL (RFC 3986 userinfo) reached the proxy.
    [Fact]
    public async Task BhvTransport001ProxyAuthenticationCredentialsAreSentToProxy()
    {
        var proxyUri = new Uri(_fixture.AuthProxyUrl);
        var proxyWithAuth =
            $"{proxyUri.Scheme}://testuser:testpass@{proxyUri.Host}:{proxyUri.Port}";
        var transport = TransportOptions.Builder().Proxy(proxyWithAuth).Build();

        var client = new DefaultApiClient(transport);
        var response = await client.SendRequestAsync(
            "GET",
            new Uri(_fixture.InternalHttpUrl + "/test/echo"),
            new Dictionary<string, string>(),
            null
        );

        Assert.Equal(200, response.StatusCode);
        Assert.Contains("\"method\"", response.Body, StringComparison.Ordinal);
    }

    [Fact]
    public async Task BhvTransport059AuthenticatingProxyRefusesARequestWithoutCredentials()
    {
        var transport = TransportOptions.Builder().Proxy(_fixture.AuthProxyUrl).Build();

        var client = new DefaultApiClient(transport);
        var response = await client.SendRequestAsync(
            "GET",
            new Uri(_fixture.InternalHttpUrl + "/test/echo"),
